package org.apache.kafka.clients.consumer.internals.events;

import org.apache.kafka.common.KafkaException;

import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;

/**
 * Base class for events signalling that a Streams rebalance callback invoked on the application
 * thread has completed. It carries the {@link CompletableFuture} that the background thread is
 * waiting on and the error, if any, produced by the callback.
 */
public abstract class StreamsCallbackCompletedEvent extends ApplicationEvent {

    private final CompletableFuture<Void> future;
    private final Optional<KafkaException> error;

    protected StreamsCallbackCompletedEvent(final Type type,
                                            final CompletableFuture<Void> future,
                                            final Optional<KafkaException> error) {
        super(type);
        this.future = Objects.requireNonNull(future);
        this.error = Objects.requireNonNull(error);
    }

    public CompletableFuture<Void> future() {
        return future;
    }

    public Optional<KafkaException> error() {
        return error;
    }

    @Override
    protected String toStringBase() {
        return super.toStringBase() +
            ", future=" + future +
            ", error=" + error;
    }
}

